"use client";

/**
 * PersonalDashboard Component
 * ============================
 * 
 * Phase 4A: Personal mode dashboard.
 * 
 * Purpose: Frequent self-monitoring and behavior shaping.
 * 
 * Primary Widgets:
 * - Financial Health Score (compact)
 * - Impulse Score (highlighted)
 * - Loss Aversion Index
 * - Last 7-day Spending Trend
 * - Top 3 Behavioral Insights
 * 
 * Secondary Section:
 * - Micro-spend detection
 * - Late-night spend indicator
 * - Category volatility chart
 * 
 * De-emphasized:
 * - EMI burden
 * - Buffer adequacy
 * - Household total net balance
 * 
 * Tone: Behavior-centric.
 */

import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import {
  Zap,
  TrendingUp,
  TrendingDown,
  AlertTriangle,
  CheckCircle,
  Info,
  Activity,
  Clock,
  IndianRupee,
} from "lucide-react";

// ============================================================
// Types
// ============================================================

interface BehavioralIndex {
  score: number;
  [key: string]: any;
}

interface BehavioralIndices {
  loss_aversion: BehavioralIndex;
  impulsivity: BehavioralIndex;
  habit_stability: BehavioralIndex;
  financial_stress: BehavioralIndex;
  savings_discipline: BehavioralIndex;
}

interface TemporalPatterns {
  trend: number;
  seasonality: number;
  volatility: number;
  weekly_pattern: Record<string, number>;
}

interface BehaviorProfile {
  temporal_patterns: TemporalPatterns;
  behavioral_indices: BehavioralIndices;
  risk_signals: {
    india_specific: {
      upi_micro_spend_flag: boolean;
      gambling_flag: boolean;
      loan_app_pattern_flag: boolean;
      emi_ratio: number;
    };
    high_impulsivity: boolean;
    high_stress: boolean;
    low_savings: boolean;
  };
  confidence: number;
  financial_health_score: number;
  data_quality: {
    transactions_90_days: number;
    total_transactions: number;
  };
}

interface Insight {
  type: "warning" | "positive" | "info";
  title: string;
  message: string;
  metric: string;
  value: any;
}

// ============================================================
// Utility Functions
// ============================================================

function getScoreColor(score: number): string {
  if (score >= 0.7) return "text-green-600";
  if (score >= 0.4) return "text-amber-600";
  return "text-red-600";
}

function getScoreBg(score: number): string {
  if (score >= 0.7) return "bg-green-100";
  if (score >= 0.4) return "bg-amber-100";
  return "bg-red-100";
}

function getInsightIcon(type: string) {
  switch (type) {
    case "warning":
      return <AlertTriangle className="h-4 w-4 text-amber-500" />;
    case "positive":
      return <CheckCircle className="h-4 w-4 text-green-500" />;
    default:
      return <Info className="h-4 w-4 text-blue-500" />;
  }
}

// Personal mode insight prioritization
function prioritizePersonalInsights(insights: Insight[]): Insight[] {
  const personalMetrics = [
    "impulse_score",
    "impulsivity",
    "loss_aversion",
    "post_income_velocity",
    "micro_txn_ratio",
    "weekend_ratio",
    "discretionary_ratio",
    "volatility",
    "trend",
  ];

  // Sort insights by personal relevance
  return insights
    .filter((insight) => {
      const metric = insight.metric.toLowerCase();
      return personalMetrics.some((m) => metric.includes(m));
    })
    .slice(0, 3);
}

// ============================================================
// Components
// ============================================================

function CompactHealthScore({ score }: { score: number }) {
  const radius = 50;
  const circumference = 2 * Math.PI * radius;
  const progress = (score / 100) * circumference;
  const offset = circumference - progress;

  return (
    <div className="flex items-center gap-4">
      <div className="relative">
        <svg width="100" height="100" className="transform -rotate-90">
          <circle
            cx="50"
            cy="50"
            r={radius}
            stroke="#e5e7eb"
            strokeWidth="8"
            fill="none"
          />
          <circle
            cx="50"
            cy="50"
            r={radius}
            stroke={score >= 70 ? "#22c55e" : score >= 40 ? "#f59e0b" : "#ef4444"}
            strokeWidth="8"
            fill="none"
            strokeDasharray={circumference}
            strokeDashoffset={offset}
            strokeLinecap="round"
          />
        </svg>
        <div className="absolute inset-0 flex items-center justify-center">
          <span className={`text-xl font-bold ${getScoreColor(score)}`}>
            {score.toFixed(0)}
          </span>
        </div>
      </div>
      <div>
        <p className="text-sm font-medium text-gray-900">Health Score</p>
        <p className="text-xs text-gray-500">
          {score >= 70 ? "Good" : score >= 40 ? "Fair" : "Needs Work"}
        </p>
      </div>
    </div>
  );
}

function ImpulseScoreCard({ impulsivity }: { impulsivity: BehavioralIndex }) {
  const score = impulsivity.score;
  const displayScore = 1 - score; // Invert for display (higher = better control)
  const percentage = (displayScore * 100).toFixed(0);

  return (
    <Card className="border-indigo-200 bg-indigo-50">
      <CardHeader className="pb-2">
        <div className="flex items-center justify-between">
          <CardTitle className="text-sm font-medium flex items-center gap-2">
            <Zap className="h-4 w-4 text-indigo-600" />
            Impulse Control
          </CardTitle>
          <Badge className={getScoreBg(displayScore)}>
            {displayScore >= 0.7 ? "Strong" : displayScore >= 0.4 ? "Moderate" : "Weak"}
          </Badge>
        </div>
      </CardHeader>
      <CardContent>
        <div className="space-y-2">
          <div className="flex items-center justify-between">
            <span className={`text-3xl font-bold ${getScoreColor(displayScore)}`}>
              {percentage}%
            </span>
          </div>
          <Progress value={parseFloat(percentage)} className="h-3" />
          <div className="grid grid-cols-2 gap-2 text-xs text-gray-600 mt-2">
            <div>
              <span className="block text-gray-400">Micro-txn</span>
              <span className="font-medium">
                {(impulsivity.micro_txn_ratio * 100).toFixed(0)}%
              </span>
            </div>
            <div>
              <span className="block text-gray-400">Weekend ↑</span>
              <span className="font-medium">
                {((impulsivity.weekend_ratio - 1) * 100).toFixed(0)}%
              </span>
            </div>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

function LossAversionCard({ lossAversion }: { lossAversion: BehavioralIndex }) {
  const score = lossAversion.score;
  const displayScore = 1 - score; // Invert (lower loss aversion = better)
  const percentage = (displayScore * 100).toFixed(0);

  return (
    <Card>
      <CardHeader className="pb-2">
        <CardTitle className="text-sm font-medium">Loss Aversion Index</CardTitle>
      </CardHeader>
      <CardContent>
        <div className="flex items-center justify-between">
          <span className={`text-2xl font-bold ${getScoreColor(displayScore)}`}>
            {percentage}%
          </span>
          <div className="text-right text-xs text-gray-500">
            <div>Post-income velocity: {(lossAversion.post_income_velocity * 100).toFixed(0)}%</div>
            <div>Large expenses: {lossAversion.large_expense_count || 0}</div>
          </div>
        </div>
        <Progress value={parseFloat(percentage)} className="h-2 mt-2" />
      </CardContent>
    </Card>
  );
}

function SpendingTrendCard({ trend, volatility }: { trend: number; volatility: number }) {
  const isUp = trend > 0;
  const trendPct = Math.abs(trend * 100).toFixed(1);

  return (
    <Card>
      <CardHeader className="pb-2">
        <CardTitle className="text-sm font-medium flex items-center gap-2">
          {isUp ? (
            <TrendingUp className="h-4 w-4 text-red-500" />
          ) : (
            <TrendingDown className="h-4 w-4 text-green-500" />
          )}
          7-Day Trend
        </CardTitle>
      </CardHeader>
      <CardContent>
        <div className="flex items-center gap-2">
          <span className={`text-2xl font-bold ${isUp ? "text-red-600" : "text-green-600"}`}>
            {isUp ? "+" : "-"}{trendPct}%
          </span>
          <span className="text-xs text-gray-500">
            {isUp ? "spending up" : "spending down"}
          </span>
        </div>
        <div className="text-xs text-gray-500 mt-1">
          Volatility: {(volatility * 100).toFixed(0)}%
        </div>
      </CardContent>
    </Card>
  );
}

function MicroSpendIndicator({ risks, impulsivity }: { risks: any; impulsivity: BehavioralIndex }) {
  const hasFlag = risks?.india_specific?.upi_micro_spend_flag;
  const microRatio = impulsivity.micro_txn_ratio || 0;

  return (
    <Alert className={hasFlag ? "border-amber-200 bg-amber-50" : "border-green-200 bg-green-50"}>
      {hasFlag ? (
        <AlertTriangle className="h-4 w-4 text-amber-600" />
      ) : (
        <CheckCircle className="h-4 w-4 text-green-600" />
      )}
      <AlertTitle className={hasFlag ? "text-amber-800" : "text-green-800"}>
        Micro-Spend Detection
      </AlertTitle>
      <AlertDescription className={hasFlag ? "text-amber-700" : "text-green-700"}>
        {hasFlag
          ? "High frequency of small UPI transactions detected. Consider tracking daily totals."
          : `Micro-transaction ratio at ${(microRatio * 100).toFixed(0)}%. No clustering detected.`}
      </AlertDescription>
    </Alert>
  );
}

function CategoryVolatilityChart({ volatility, categoryCV }: { volatility: number; categoryCV: number }) {
  return (
    <Card>
      <CardHeader className="pb-2">
        <CardTitle className="text-sm font-medium">Category Volatility</CardTitle>
      </CardHeader>
      <CardContent>
        <div className="space-y-3">
          <div>
            <div className="flex justify-between text-xs mb-1">
              <span className="text-gray-500">Daily Variance</span>
              <span className="font-medium">{(volatility * 100).toFixed(0)}%</span>
            </div>
            <Progress value={volatility * 100} className="h-2" />
          </div>
          <div>
            <div className="flex justify-between text-xs mb-1">
              <span className="text-gray-500">Category CV</span>
              <span className="font-medium">{(categoryCV * 100).toFixed(0)}%</span>
            </div>
            <Progress value={categoryCV * 100} className="h-2" />
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

// ============================================================
// Main Component
// ============================================================

interface PersonalDashboardProps {
  profile: BehaviorProfile;
  insights: Insight[];
}

export function PersonalDashboard({ profile, insights }: PersonalDashboardProps) {
  const indices = profile.behavioral_indices;
  const temporal = profile.temporal_patterns;
  const risks = profile.risk_signals;

  // Prioritize insights for personal mode
  const personalInsights = prioritizePersonalInsights(insights);

  return (
    <div className="space-y-6">
      {/* Primary Section */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        {/* Health Score - Compact */}
        <Card>
          <CardContent className="pt-4">
            <CompactHealthScore score={profile.financial_health_score} />
          </CardContent>
        </Card>

        {/* Impulse Score - Highlighted */}
        <ImpulseScoreCard impulsivity={indices.impulsivity} />

        {/* Loss Aversion */}
        <LossAversionCard lossAversion={indices.loss_aversion} />

        {/* Spending Trend */}
        <SpendingTrendCard
          trend={temporal.trend}
          volatility={temporal.volatility}
        />
      </div>

      {/* Top 3 Behavioral Insights */}
      <Card>
        <CardHeader>
          <CardTitle className="text-base flex items-center gap-2">
            <Activity className="h-4 w-4" />
            Top Behavioral Insights
          </CardTitle>
          <CardDescription>
            Personalized observations for behavior improvement
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="space-y-3">
            {personalInsights.length > 0 ? (
              personalInsights.map((insight, i) => (
                <div
                  key={`insight-${i}-${insight.metric}`}
                  className={`p-3 rounded-lg border ${
                    insight.type === "warning"
                      ? "border-amber-200 bg-amber-50"
                      : insight.type === "positive"
                      ? "border-green-200 bg-green-50"
                      : "border-blue-200 bg-blue-50"
                  }`}
                >
                  <div className="flex items-start gap-2">
                    {getInsightIcon(insight.type)}
                    <div className="flex-1">
                      <h4 className="font-medium text-sm">{insight.title}</h4>
                      <p className="text-xs text-gray-600 mt-1">{insight.message}</p>
                    </div>
                  </div>
                </div>
              ))
            ) : (
              <div className="text-center py-4 text-gray-500 text-sm">
                No personal insights available. Add more transactions for analysis.
              </div>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Secondary Section */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {/* Micro-spend Detection */}
        <MicroSpendIndicator
          risks={risks}
          impulsivity={indices.impulsivity}
        />

        {/* Category Volatility */}
        <CategoryVolatilityChart
          volatility={temporal.volatility}
          categoryCV={indices.habit_stability.category_cv}
        />
      </div>

      {/* Quick Stats Row */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
        <div className="bg-gray-50 rounded-lg p-3">
          <div className="flex items-center gap-2 text-gray-500 text-xs">
            <Clock className="h-3 w-3" />
            <span>Confidence</span>
          </div>
          <p className="text-lg font-semibold mt-1">
            {(profile.confidence * 100).toFixed(0)}%
          </p>
        </div>
        <div className="bg-gray-50 rounded-lg p-3">
          <div className="flex items-center gap-2 text-gray-500 text-xs">
            <IndianRupee className="h-3 w-3" />
            <span>Discretionary</span>
          </div>
          <p className="text-lg font-semibold mt-1">
            {(indices.impulsivity.discretionary_ratio * 100).toFixed(0)}%
          </p>
        </div>
        <div className="bg-gray-50 rounded-lg p-3">
          <div className="flex items-center gap-2 text-gray-500 text-xs">
            <Activity className="h-3 w-3" />
            <span>Habit Stability</span>
          </div>
          <p className="text-lg font-semibold mt-1">
            {(indices.habit_stability.score * 100).toFixed(0)}%
          </p>
        </div>
        <div className="bg-gray-50 rounded-lg p-3">
          <div className="flex items-center gap-2 text-gray-500 text-xs">
            <Zap className="h-3 w-3" />
            <span>Recurring</span>
          </div>
          <p className="text-lg font-semibold mt-1">
            {indices.habit_stability.recurring_count || 0}
          </p>
        </div>
      </div>
    </div>
  );
}