"use client";

/**
 * Dashboard Page
 * ===============
 * 
 * Phase 4A: Dual Mode Dashboard.
 * 
 * Single source of truth: GET /api/behavior/summary
 * Two interpretation modes: personal | family
 * 
 * Modes affect:
 * - Metric prioritization
 * - Layout
 * - Emphasis
 * - Insight ordering
 * 
 * NOT the calculations.
 */

import { useState, useEffect } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { AlertTriangle, Info } from "lucide-react";

import { ModeToggle, useDashboardMode, DashboardMode } from "@/components/ModeToggle";
import { PersonalDashboard } from "@/components/PersonalDashboard";
import { FamilyDashboard } from "@/components/FamilyDashboard";

// ============================================================
// Types
// ============================================================

interface BehavioralIndex {
  score: number;
  [key: string]: any;
}

interface BehavioralIndices {
  loss_aversion: BehavioralIndex;
  impulsivity: BehavioralIndex;
  habit_stability: BehavioralIndex;
  financial_stress: BehavioralIndex;
  savings_discipline: BehavioralIndex;
}

interface TemporalPatterns {
  trend: number;
  seasonality: number;
  volatility: number;
  weekly_pattern: Record<string, number>;
}

interface BehaviorProfile {
  temporal_patterns: TemporalPatterns;
  behavioral_indices: BehavioralIndices;
  risk_signals: {
    india_specific: {
      upi_micro_spend_flag: boolean;
      gambling_flag: boolean;
      loan_app_pattern_flag: boolean;
      emi_ratio: number;
      gambling_transaction_count?: number;
      loan_credit_count?: number;
    };
    high_impulsivity: boolean;
    high_stress: boolean;
    low_savings: boolean;
  };
  confidence: number;
  financial_health_score: number;
  data_quality: {
    transactions_90_days: number;
    total_transactions: number;
  };
}

interface Insight {
  type: "warning" | "positive" | "info";
  title: string;
  message: string;
  metric: string;
  value: any;
}

interface InsightsResponse {
  insights: Insight[];
  nudges: any[];
  top_nudge: any;
  summary: string;
  financial_health_score: number;
  confidence: number;
}

// ============================================================
// Main Page Component
// ============================================================

export default function DashboardPage() {
  const [mode, setMode] = useDashboardMode();
  const [profile, setProfile] = useState<BehaviorProfile | null>(null);
  const [insights, setInsights] = useState<Insight[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Fetch data on mount
  useEffect(() => {
    async function fetchData() {
      try {
        const [profileRes, insightsRes] = await Promise.all([
          fetch("http://localhost:8000/api/behavior/summary"),
          fetch("http://localhost:8000/api/behavior/insights"),
        ]);

        if (!profileRes.ok || !insightsRes.ok) {
          throw new Error("Failed to fetch behavior data");
        }

        const profileData = await profileRes.json();
        const insightsData: InsightsResponse = await insightsRes.json();

        setProfile(profileData);
        setInsights(insightsData.insights || []);
      } catch (err) {
        setError(err instanceof Error ? err.message : "An error occurred");
      } finally {
        setLoading(false);
      }
    }

    fetchData();
  }, []);

  // Loading state
  if (loading) {
    return (
      <div className="container mx-auto py-6 space-y-6">
        <div className="flex items-center justify-between">
          <Skeleton className="h-8 w-48" />
          <Skeleton className="h-10 w-64" />
        </div>
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <Skeleton className="h-32" />
          <Skeleton className="h-32" />
          <Skeleton className="h-32" />
          <Skeleton className="h-32" />
        </div>
        <Skeleton className="h-64" />
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <Skeleton className="h-48" />
          <Skeleton className="h-48" />
        </div>
      </div>
    );
  }

  // Error state
  if (error) {
    return (
      <div className="container mx-auto py-6">
        <Alert variant="destructive">
          <AlertTriangle className="h-4 w-4" />
          <AlertTitle>Error</AlertTitle>
          <AlertDescription>{error}</AlertDescription>
        </Alert>
      </div>
    );
  }

  // No data state
  if (!profile) {
    return (
      <div className="container mx-auto py-6">
        <Alert>
          <Info className="h-4 w-4" />
          <AlertTitle>No Data</AlertTitle>
          <AlertDescription>
            Add transactions to see behavioral insights.
          </AlertDescription>
        </Alert>
      </div>
    );
  }

  return (
    <div className="container mx-auto py-6 space-y-6">
      {/* Header with Mode Toggle */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold">
            {mode === "personal" ? "Personal Dashboard" : "Family Dashboard"}
          </h1>
          <p className="text-gray-500 text-sm">
            {mode === "personal"
              ? "Behavior-centric view for self-monitoring"
              : "Stability-centric view for household planning"}
          </p>
        </div>
        <ModeToggle mode={mode} onModeChange={setMode} />
      </div>

      {/* Mode-specific Dashboard */}
      {mode === "personal" ? (
        <PersonalDashboard profile={profile} insights={insights} />
      ) : (
        <FamilyDashboard profile={profile} insights={insights} />
      )}

      {/* Data Quality Footer */}
      <Card className="bg-gray-50 border-gray-200">
        <CardContent className="py-3">
          <div className="flex items-center justify-between text-xs text-gray-500">
            <span>
              Based on {profile.data_quality.transactions_90_days} transactions (90 days)
            </span>
            <span>
              Total: {profile.data_quality.total_transactions} transactions
            </span>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}