"use client";

/**
 * ModeToggle Component
 * ====================
 * 
 * Phase 4A: Dual Mode Dashboard toggle.
 * 
 * Switches between Personal and Family dashboard modes.
 * Persists preference to localStorage.
 * 
 * No backend changes - purely client-side presentation toggle.
 */

import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { User, Users } from "lucide-react";

export type DashboardMode = "personal" | "family";

interface ModeToggleProps {
  mode: DashboardMode;
  onModeChange: (mode: DashboardMode) => void;
}

const STORAGE_KEY = "clariFin_dashboard_mode";

export function ModeToggle({ mode, onModeChange }: ModeToggleProps) {
  // Initialize from localStorage on mount
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved === "personal" || saved === "family") {
      onModeChange(saved);
    }
  }, []);

  // Persist to localStorage on change
  const handleModeChange = (newMode: DashboardMode) => {
    localStorage.setItem(STORAGE_KEY, newMode);
    onModeChange(newMode);
  };

  return (
    <div className="flex items-center gap-1 p-1 bg-gray-100 rounded-lg">
      <Button
        variant={mode === "personal" ? "default" : "ghost"}
        size="sm"
        onClick={() => handleModeChange("personal")}
        className={`flex items-center gap-2 ${
          mode === "personal"
            ? "bg-indigo-600 text-white hover:bg-indigo-700"
            : "text-gray-600 hover:text-gray-900"
        }`}
      >
        <User className="h-4 w-4" />
        <span>Personal</span>
      </Button>
      <Button
        variant={mode === "family" ? "default" : "ghost"}
        size="sm"
        onClick={() => handleModeChange("family")}
        className={`flex items-center gap-2 ${
          mode === "family"
            ? "bg-emerald-600 text-white hover:bg-emerald-700"
            : "text-gray-600 hover:text-gray-900"
        }`}
      >
        <Users className="h-4 w-4" />
        <span>Family</span>
      </Button>
    </div>
  );
}

// Hook for managing mode with localStorage persistence
export function useDashboardMode(): [DashboardMode, (mode: DashboardMode) => void] {
  const [mode, setModeState] = useState<DashboardMode>("personal");

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved === "personal" || saved === "family") {
      setModeState(saved);
    }
  }, []);

  const setMode = (newMode: DashboardMode) => {
    localStorage.setItem(STORAGE_KEY, newMode);
    setModeState(newMode);
  };

  return [mode, setMode];
}